-- do the FEC twins' IE vendors (caging/leads/phonebank block) also show up as payees of any 527, and of the 19?
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
p AS (SELECT column1 pat FROM VALUES ('%CLOUD DATA SERV%'),('%WIRED4DATA%'),('%WIRED 4 DATA%'),('%STANDARD DATA SERV%'),('%LAV SERVICES%'),('%RIDGE INNOVATIVE%'),('%EYP CONSULT%'),('%BOWLINE%'),('%LIVE TRANSFERS%')),
b AS (SELECT DISTINCT b.EIN, b.ORG_NAME, UPPER(RECIPIENT_NAME) r, RECIPIENT_STATE st, EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, p.pat FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES b JOIN p ON UPPER(b.RECIPIENT_NAME) LIKE p.pat)
SELECT pat, b.EIN, MAX(ORG_NAME) org, IFF(MAX(g.EIN) IS NULL,'N','Y') in19, LEFT(MAX(r),40) payee, MAX(st) st, ROUND(SUM(a)/1e6,3) m, MIN(d) d0, MAX(d) d1
FROM b LEFT JOIN g ON g.EIN=b.EIN GROUP BY pat, b.EIN ORDER BY pat, m DESC
